{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "约翰·马斯顿（张牧之/张麻子）",
      "role": "protagonist",
      "identity": "穿越民国的西部牛仔/传奇悍匪张麻子",
      "traits": [
        "沉默寡言（子弹是他唯一的语言）",
        "孤狼气质（人群中永远站在最远处）",
        "重情重义（为兄弟可以赴死）",
        "暴力美学信徒（杀人如艺术，干净利落）",
        "自我救赎执念（过去的罪孽如影随形）"
      ],
      "overt_motivation": "找到亚瑟·摩根，弄清楚范德林帮成员穿越到民国后的真相",
      "covert_motivation": "赎罪——他在西部世界背叛过亚瑟，这次要把欠的还回去",
      "secret_fear": "发现亚瑟已经死了，或者更糟——亚瑟选择留在这个时代是因为不想再见到他",
      "misperception_of_other": "以为黄四郎只是个普通的民国土霸王，不知道他就是范德林帮的叛徒迈卡·贝尔",
      "hidden_connection": "他手上的左轮是亚瑟送的遗物——子弹打光的那天，就是他死的那天"
    },
    {
      "name": "黄四郎（迈卡·贝尔）",
      "role": "deuteragonist",
      "identity": "鹅城首富/民国大恶霸/范德林帮叛徒",
      "traits": [
        "阴险狡诈（从不正面对决）",
        "贪婪无度（钱、权、命都要）",
        "口才了得（能把黑的说成白的）",
        "内心虚弱（用权势掩盖恐惧）",
        "嗜杀成性（杀人的快感是他唯一真实的情感）"
      ],
      "overt_motivation": "维护鹅城的统治地位，消灭一切威胁",
      "covert_motivation": "彻底抹除西部世界的身份，让'迈卡·贝尔'永远死去，让'黄四郎'活下去",
      "secret_fear": "约翰·马斯顿的到来，意味着过去追上了他——范德林帮的血债要用命来还",
      "misperception_of_other": "以为约翰只是个普通的匪帮头子，直到看到那把熟悉的左轮手枪",
      "hidden_connection": "当年是他出卖了范德林帮，导致亚瑟重伤逃亡——穿越是意外，但罪孽是选择"
    }
  ],
  "supporting_characters": [
    {
      "name": "老六（六子/小六）",
      "function": "反转点",
      "identity": "张麻子的义子/凉粉事件的'死者'",
      "description": "原本应该剖腹明志的少年，因为约翰的死眼技能在最后一刻觉醒，反杀胡万。他是故事的导火索，也是约翰在民国世界最坚定的追随者。年轻气盛，快意恩仇，像极了年轻时的约翰。后期发现他可能是亚瑟·摩根在民国的转世/后代。"
    },
    {
      "name": "汤师爷（马邦德）",
      "function": "助力",
      "identity": "假县长/真师爷/信息掮客",
      "description": "民国世界的土著，贪财怕死但有底线。他是约翰融入鹅城的桥梁，懂得这里的规则和潜规则。他的台词梗密度最高，负责喜剧效果。与约翰形成'话痨vs沉默'的反差搭档。"
    },
    {
      "name": "花姐",
      "function": "助力",
      "identity": "鹅城青楼老板娘/地下情报网负责人",
      "description": "鹅城最懂人心的女人，表面风尘，实则精明。她手下的姑娘们是鹅城最好的眼线。她对约翰有好感，但更欣赏他的孤独——'只有真正孤独的人，才配得上真正的爱'。她知道很多关于黄四郎的秘密。"
    },
    {
      "name": "胡万",
      "function": "阻碍",
      "identity": "黄四郎的首席打手/凉粉事件的始作俑者",
      "description": "开场就被六子反杀，但他只是个'第一滴血'，真正的战争才刚开始。他的死是一个信号——告诉鹅城所有人，张麻子不是来做生意的，是来杀人的。"
    },
    {
      "name": "武举人",
      "function": "阻碍",
      "identity": "鹅城民团头领/黄四郎的武装力量",
      "description": "手下有三百民团，是黄四郎的武力后盾。他粗犷但不蠢，对黄四郎的忠诚来自利益而非信仰。当利益天平倾斜时，他会做出自己的选择。"
    },
    {
      "name": "假麻子",
      "function": "反转点",
      "identity": "黄四郎养的替身",
      "description": "黄四郎为了钓张麻子上钩而培养的替身，外形神似，但眼神永远学不像——'他杀过的人没我多，他的眼睛里没有鬼'。后期成为约翰攻破黄四郎心理防线的关键棋子。"
    },
    {
      "name": "老三",
      "function": "助力",
      "identity": "张麻子手下的老匪/沉默的狙击手",
      "description": "跟张麻子最久的兄弟，话比张麻子还少，但枪法一流。他是约翰'沉默语言'的呼应者——两个不说话的人，在枪响的瞬间完成所有交流。"
    },
    {
      "name": "达奇（荷兰人）",
      "function": "反转点",
      "identity": "范德林帮帮主/穿越后化身民国军阀幕僚",
      "description": "范德林帮曾经的精神领袖，穿越到民国后成为某个军阀的幕僚。他是约翰寻找亚瑟的关键线索——'亚瑟最后一次被看见，是在跟达奇告别之后'。他的出现将揭开范德林帮分崩离析的真相。"
    }
  ],
  "relationship_dynamics": "【约翰-黄四郎】：表面是民国匪帮与土霸王的对决，实际是范德林帮旧恨的延续。初期约翰不知道黄四郎就是迈卡，只觉得这个人'杀人的方式很熟悉'。中期通过各种线索逐渐确认身份，从'鹅城之战'升级为'宿命复仇'。高潮时两人对峙，迈卡说出当年出卖亚瑟的真相，约翰的复仇从'为兄弟'变成'为救赎'。\n\n【约翰-六子】：父子般的羁绊。约翰在六子身上看到年轻的自己——冲动、重义、不计后果。六子崇拜约翰的枪法和沉默，约翰则试图保护六子不走自己的老路。当六子的真实身份揭露（亚瑟的血脉？），两人的关系从'义父子'升级为'命运共同体'。\n\n【约翰-汤师爷】：喜剧CP。汤师爷话多，约翰话少。汤师爷怕死，约翰不怕死。汤师爷什么都要，约翰只要答案。两人的对话是全文最密集的台词梗来源。但在关键时刻，汤师爷会展现出超越怕死的勇气——'有些钱赚了会睡不着觉，有些人死了会更睡不着'。\n\n【约翰-花姐】：暧昧而克制。花姐是唯一看穿约翰孤独的人，但约翰心里只有救赎和复仇。两人之间有chemistry，但永远不会发生——'他的心装不下活人，只装得下死人'。\n\n【黄四郎-武举人】：利益同盟。武举人是黄四郎的爪牙，但不是走狗。当约翰的攻势让黄四郎摇摇欲坠时，武举人会重新计算利益——'我跟你不是一条船，我只是租了你的船'。"
}
"}

